mapper.select:
SELECT ISTSFDG AS "stsfdg", SSTSFDG_CN AS "content"
  FROM TB_PROM_STSFDG
 WHERE IPROM_NO = #{promNo} AND SINS_ID = #{userId}

SELECT * FROM ( SELECT rownum rn, TB.* FROM ( SELECT p.IPROM_NO AS "promNo", p.STITLE AS "title", p.ILAW_NO AS "lawNo", c.SNAME AS "cateNm", ob.ORGNZT_NM AS "buseoNm", p.SSTSFDG_YN AS "stsfdgYn", p.SEXISTING_YN AS "existingYn", p.SDISP_YN AS "dispYn", NVL(a.CNT, 0) AS "cnt", a.AVGV AS "avg",
NVL2(a.LASTDT, SUBSTR(a.LASTDT, 1, 4) || '-' || SUBSTR(a.LASTDT, 5, 2) || '-' || SUBSTR(a.LASTDT, 7, 2), NULL) AS "lastDt"
ORDER BY NVL(a.CNT, 0) DESC, p.STITLE, p.ILAW_NO DESC, p.IPROM_NO DESC ) TB ) WHERE rn BETWEEN #{firstIndex}+1 AND #{firstIndex}+#{recordCountPerPage}
